builder.Services.AddHttpClient<IInventoryClient, InventoryClient>(client =>
{
    client.BaseAddress = new Uri("https://inventory.internal/");
    client.Timeout = Timeout.InfiniteTimeSpan; // Polly timeout owns deadline
})
.AddStandardResilienceHandler(options =>
{
    options.Retry.MaxRetryAttempts = 3;
    options.Retry.Delay = TimeSpan.FromMilliseconds(200);
    options.CircuitBreaker.MinimumThroughput = 10;
    options.CircuitBreaker.BreakDuration = TimeSpan.FromSeconds(30);
    options.TotalRequestTimeout.Timeout = TimeSpan.FromSeconds(5);
});

var pipeline = new ResiliencePipelineBuilder<HttpResponseMessage>()
    .AddRetry(new RetryStrategyOptions<HttpResponseMessage>
    {
        MaxRetryAttempts = 3,
        Delay = TimeSpan.FromSeconds(1),
        BackoffType = DelayBackoffType.Exponential,
        ShouldHandle = new PredicateBuilder<HttpResponseMessage>()
            .Handle<HttpRequestException>()
            .HandleResult(r => (int)r.StatusCode >= 500)
    })
    .AddCircuitBreaker(new CircuitBreakerStrategyOptions<HttpResponseMessage>
    {
        FailureRatio = 0.5,
        MinimumThroughput = 20,
        BreakDuration = TimeSpan.FromSeconds(30),
        ShouldHandle = new PredicateBuilder<HttpResponseMessage>()
            .Handle<HttpRequestException>()
            .HandleResult(r => (int)r.StatusCode >= 500)
    })
    .Build();

var response = await pipeline.ExecuteAsync(
    async ct => await httpClient.GetAsync("/api/stock/42", ct));

app.MapGet("/api/orders/{id}", async (int id, IOrdersService svc) =>
{
    try
    {
        return Results.Ok(await svc.GetOrderAsync(id));
    }
    catch (BrokenCircuitException)
    {
        return Results.Problem(
            title: "Dependency temporarily unavailable",
            statusCode: StatusCodes.Status503ServiceUnavailable,
            extensions: new Dictionary<string, object?> { ["retryAfter"] = 30 });
    }
});

options.CircuitBreaker.OnOpened = args =>
{
    logger.LogError("Circuit OPEN for {Client} duration={Duration}",
        nameof(InventoryClient), args.BreakDuration);
    return default;
};
options.CircuitBreaker.OnClosed = args =>
{
    logger.LogInformation("Circuit CLOSED for {Client}", nameof(InventoryClient));
    return default;
};
